reference_solution:
def maximum_courses(courses):
    import heapq
    selected = []
    elapsed = 0
    for duration, deadline in sorted(courses, key=lambda course: course[1]):
        heapq.heappush(selected, -duration)
        elapsed += duration
        if elapsed > deadline:
            elapsed += heapq.heappop(selected)
    return len(selected)

